using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ActorTimelineOperations
{
    private readonly ActorDataOperations _data=new();private readonly ActorDefinitionOperations _definitions=new();private readonly ActorRuntimeOperations _runtime=new();
    private static void Assign(GArray target,GArray source){var copy=source.Duplicate();target.Clear();foreach(var value in copy)target.Add(value);}
    private static void History(RefCounted owner,string label,string forward,GArray after,string backward,GArray before,bool execute=true){var history=owner.Get("history").As<UndoRedo>();var action=new ActorTimelineHistoryAction(owner,forward,after,backward,before);history.CreateAction(label);history.AddDoMethod(new Callable(action,nameof(ActorTimelineHistoryAction.perform_do)));history.AddUndoMethod(new Callable(action,nameof(ActorTimelineHistoryAction.perform_undo)));history.AddDoReference(action);history.CommitAction(execute);}
    public Settings audio_snapshot(RefCounted owner,Resource actor){var clip=clip_for_actor_id(owner,actor.Get("id").AsString())!;return new Settings{["actor"]=actor,["values"]=actor.Get("values").AsGodotDictionary().Duplicate(true),["clip"]=clip,["duration"]=clip.Get("duration"),["offset"]=clip.Get("source_offset"),["speed"]=clip.Get("playback_speed"),["layer"]=clip.Get("layer")};}
    public void restore_audio(RefCounted owner,Settings state){var actor=state["actor"].As<Resource>();actor.Set("values",state["values"].AsGodotDictionary().Duplicate(true));var clip=state["clip"].As<Resource>();clip.Set("duration",state["duration"]);clip.Set("source_offset",state["offset"]);clip.Set("playback_speed",state["speed"]);clip.Set("layer",state["layer"]);actor.EmitChanged();Changed(owner);}
    public double minimum_duration(RefCounted owner,Resource clip){var actor=actor_for_id(owner,clip.Get("actor_id").AsString());double length=actor!=null&&(actor.Get("type_id").AsString() is "audio" or "video" or "video_2d")?GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("length",actor).AsDouble():0;return length>0?Math.Min(.1,Math.Min(clip.Get("duration").AsDouble(),length/clip.Get("playback_speed").AsDouble())):.1;}
    public Godot.Collections.Array<string> linked_clip_ids(RefCounted owner,GArray ids)
    {
        var result=new Godot.Collections.Array<string>();foreach(var id in ids)result.Add(id.AsString());for(int cursor=0;cursor<result.Count;cursor++){int index=index_of(owner,result[cursor]);if(index<0)continue;var parent=Actors(owner)[index].As<Resource>();if(!parent.Get("link_timeline_children").AsBool())continue;foreach(var value in Actors(owner)){var actor=value.As<Resource>();if(actor.Get("parent_id").AsString()!=parent.Get("id").AsString())continue;var child=clip_for_actor_id(owner,actor.Get("id").AsString());if(child!=null&&!result.Contains(child.Get("id").AsString()))result.Add(child.Get("id").AsString());}}return result;
    }
    public void set_timeline_children_linked(RefCounted owner,string id,bool linked){var actor=actor_for_id(owner,id);if(actor==null||actor.Get("link_timeline_children").AsBool()==linked)return;History(owner,linked?"Link Children":"Unlink Children","_set_children_link",new GArray{actor,linked},"_set_children_link",new GArray{actor,actor.Get("link_timeline_children")});}
    public void set_children_link(RefCounted owner,Resource actor,bool linked){actor.Set("link_timeline_children",linked);actor.EmitChanged();Changed(owner);}
    public Settings media_snapshot(RefCounted owner)
    {
        var states=new Godot.Collections.Array<Settings>();foreach(var value in Actors(owner)){var actor=value.As<Resource>();states.Add(new Settings{["actor"]=actor,["values"]=actor.Get("values").AsGodotDictionary().Duplicate(),["parent"]=actor.Get("parent_id"),["visible"]=actor.Get("show_timeline_children"),["linked"]=actor.Get("link_timeline_children")});}var timings=new Settings();foreach(var value in Clips(owner)){var clip=value.As<Resource>();timings[clip.Get("id")]=new Settings{["start"]=clip.Get("start_time"),["duration"]=clip.Get("duration"),["offset"]=clip.Get("source_offset"),["layer"]=clip.Get("layer")};}return new Settings{["actors"]=Actors(owner).Duplicate(),["clips"]=Clips(owner).Duplicate(),["states"]=states,["timings"]=timings,["selection"]=Selected(owner).Duplicate(),["primary"]=owner.Get("selected_id"),["layer"]=owner.Get("selected_layer")};
    }
    public void restore_media(RefCounted owner,Settings state)
    {
        Assign(Actors(owner),state["actors"].AsGodotArray());Assign(Clips(owner),state["clips"].AsGodotArray());foreach(var value in state["states"].AsGodotArray()){var entry=value.AsGodotDictionary();var actor=entry["actor"].As<Resource>();actor.Set("values",entry["values"].AsGodotDictionary().Duplicate());actor.Set("parent_id",entry["parent"]);actor.Set("show_timeline_children",entry["visible"]);actor.Set("link_timeline_children",entry["linked"]);actor.EmitChanged();}var timings=state["timings"].AsGodotDictionary();foreach(var value in Clips(owner)){var clip=value.As<Resource>();var timing=timings[clip.Get("id")].AsGodotDictionary();clip.Set("start_time",timing["start"]);clip.Set("duration",timing["duration"]);clip.Set("source_offset",timing["offset"]);clip.Set("layer",timing["layer"]);}Assign(Selected(owner),state["selection"].AsGodotArray());owner.Set("selected_id",state["primary"]);owner.Set("selected_layer",state["layer"]);Changed(owner);
    }
    public void commit_media(RefCounted owner,Settings before,string label)=>History(owner,label,"restore_media",new GArray{media_snapshot(owner)},"restore_media",new GArray{before});
    public Resource create_section(RefCounted owner){var section=new ActorSection();section.Set("id",_data.new_id());section.Set("display_name","Section "+(owner.Get("sections").AsGodotArray().Count+1));History(owner,"Create Section","_insert_section",new GArray{section},"_remove_section",new GArray{section,owner.Get("selected_section_id")});return section;}
    public void insert_section(RefCounted owner,Resource section){owner.Get("sections").AsGodotArray().Add(section);select_section(owner,section.Get("id").AsString());}
    public void remove_section(RefCounted owner,Resource section,string previous){owner.Get("sections").AsGodotArray().Remove(section);select_section(owner,previous);}
    public void rename_section(RefCounted owner,string id,string name){var section=section_for_id(owner,id);name=name.Trim();if(section==null||name.Length==0||name==section.Get("display_name").AsString())return;History(owner,"Rename Section","_set_section_name",new GArray{section,name},"_set_section_name",new GArray{section,section.Get("display_name")});}
    public void set_section_name(RefCounted owner,Resource section,string name){section.Set("display_name",name);section.EmitChanged();Changed(owner);}
    public bool revealed_layer_fits(RefCounted owner,Resource actor,Resource clip,int layer,GArray reserved)
    {
        foreach(var value in reserved){var entry=value.AsGodotDictionary();var other=entry["clip"].As<Resource>();if(entry["layer"].AsInt32()==layer&&actors_obstruct(owner,actor,entry["actor"].As<Resource>())&&clip.Get("start_time").AsDouble()<other.Get("start_time").AsDouble()+other.Get("duration").AsDouble()-.000001&&clip.Get("start_time").AsDouble()+clip.Get("duration").AsDouble()>other.Get("start_time").AsDouble()+.000001)return false;}return true;
    }
    public void set_timeline_children_visible(RefCounted owner,string id,bool visible)
    {
        var actor=actor_for_id(owner,id);if(actor==null||actor.Get("show_timeline_children").AsBool()==visible)return;bool original=actor.Get("show_timeline_children").AsBool();var before=new Settings();var after=new Settings();if(visible){actor.Set("show_timeline_children",true);try{var reserved=new GArray();var descendants=new GArray();var actors=Actors(owner);var clips=Clips(owner);for(int i=0;i<clips.Count;i++){var candidate=actors[i].As<Resource>();if(candidate.Get("section_id").AsString()!=actor.Get("section_id").AsString())continue;if(is_actor_ancestor(owner,id,candidate))descendants.Add(clips[i]);else reserved.Add(new Settings{["actor"]=candidate,["clip"]=clips[i],["layer"]=clips[i].As<Resource>().Get("layer")});}foreach(var value in descendants){var clip=value.As<Resource>();var descendant=actor_for_id(owner,clip.Get("actor_id").AsString())!;int layer=clip.Get("layer").AsInt32();while(!revealed_layer_fits(owner,descendant,clip,layer,reserved))layer++;reserved.Add(new Settings{["actor"]=descendant,["clip"]=clip,["layer"]=layer});if(layer!=clip.Get("layer").AsInt32()){before[clip.Get("id")]=clip.Get("layer");after[clip.Get("id")]=layer;}}}finally{actor.Set("show_timeline_children",original);}}History(owner,visible?"Show Timeline Children":"Hide Timeline Children","_set_timeline_children_visible",new GArray{actor,visible,after},"_set_timeline_children_visible",new GArray{actor,original,before});
    }
    public void apply_timeline_children_visible(RefCounted owner,Resource actor,bool visible,Settings layers){actor.Set("show_timeline_children",visible);foreach(var entry in layers){int index=index_of(owner,entry.Key.AsString());if(index>=0){var clip=Clips(owner)[index].As<Resource>();clip.Set("layer",entry.Value);clip.EmitChanged();}}var selected=selected_clip(owner);if(selected!=null)owner.Set("selected_layer",selected.Get("layer"));actor.EmitChanged();Changed(owner);}
}
